import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Preboot Execution Environment","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/preboot-execution-environment.md","filePath":"d/ad/preboot-execution-environment.md","lastUpdated":1781102819000}`),a={name:`d/ad/preboot-execution-environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/preboot-execution-environment.md for this page in Markdown format</div><h1 id="preboot-execution-environment" tabindex="-1">Preboot Execution Environment <a class="header-anchor" href="#preboot-execution-environment" aria-label="Permalink to “Preboot Execution Environment”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Preboot Execution Environment (PXE boot) is a network protocol that allows starting a computer via the network and providing an operating system or software without needing a local hard disk or optical drive.</p><p>If misconfigured, PXE boot can be misused to open a shell with system authorizations when a new computer is started to create a local user with administrator authorizations. This allows the (often later domain-joined) device to be used with local administration authorizations.</p><p>To use PXE boot effectively and to automate the process of operating system provisioning, software tools like System Center Configuration Manager (SCCM) from Microsoft are often used. SCCM is a comprehensive management and deployment tool for IT infrastructures. It enables the central administration of operating systems, applications, and settings in a network.</p><p>With SCCM, administrators can set up PXE boot environments to configure computers on the network via network startup and automatically install operating systems or software. SCCM offers functions such as creating images, deploying software packages, collecting inventory data, and managing updates. It simplifies the process of operating system provisioning and enables centralized management and configuration of the network computers.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Disable the debug mode in boot images.</li><li>If possible, only perform PXE deployments in isolated networks.</li><li>Ensure that the password for starting the installation process is sufficiently secure.</li></ul>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};